	private static final int PAGE_SHIFT = 6;
	private static final int PAGE_SIZE = 1 << PAGE_SHIFT;
	// Includes five page arrays, per-cell weak-reference metadata, the page object, and alignment.
	private static final long PAGE_BYTES = 16_384L;

	private final NativeResultMaterializerPlan plan;
	private final LmdbQueryMemoryManager.QueryLedger ledger;
